export { createCustomClient } from "jsr:@brad-jones/deno-net-open-api-client@0.1.6";

/**
 * Create a client with all available operations.
 * This is convenient but will include all operations in your bundle.
 * For better tree-shaking, use createCustomClient() to select specific operations.
 */
export function createClient(config: OpenAPIClientConfig) {
  return createCustomClient(config, {
    getFiles,
    uploadFile,
    getFile,
    updateFile,
    deleteFile,
    uploadFileToFolder,
    getFileContent,
    getFileAssociations,
    createFileAssociation,
    deleteFileAssociation,
    getAssociationsByObject,
    getAssociationsCount,
    getFolders,
    createFolder,
    getFolder,
    updateFolder,
    deleteFolder,
    getInbox,
  });
}
